class Solution:
    def missingSeat(self, seats: List[int]) -> int:
        for s in range(len(seats) + 1):
            if s not in seats:
                return s
        return -1

code.java:
class Solution {
    public int missingSeat(int[] seats) {
        for (int s = 0; s <= seats.length; s++) {
            boolean taken = false;
            for (int v : seats) if (v == s) { taken = true; break; }
            if (!taken) return s;
        }
        return -1;
    }
}

