class Solution {
public:
    int missingSeat(vector<int>& seats) {
        for (int s = 0; s <= (int) seats.size(); s++) {
            if (find(seats.begin(), seats.end(), s) == seats.end()) return s;
        }
        return -1;
    }
};

code.c:
int missingSeat(int* seats, int seatsSize) {
    for (int s = 0; s <= seatsSize; s++) {
        bool taken = false;
        for (int i = 0; i < seatsSize && !taken; i++) taken = seats[i] == s;
        if (!taken) return s;
    }
    return -1;
}

