class Solution:
    def missingSeat(self, seats: List[int]) -> int:
        taken = [False] * (len(seats) + 1)
        for s in seats:
            taken[s] = True
        return taken.index(False)

code.java:
class Solution {
    public int missingSeat(int[] seats) {
        boolean[] taken = new boolean[seats.length + 1];
        for (int s : seats) taken[s] = true;
        int s = 0;
        while (taken[s]) s++;
        return s;
    }
}

