code.c:
int missingSeat(int* seats, int seatsSize) {
    bool* taken = calloc(seatsSize + 1, sizeof(bool));
    for (int i = 0; i < seatsSize; i++) taken[seats[i]] = true;
    int s = 0;
    while (taken[s]) s++;
    free(taken);
    return s;
}

code.python:
class Solution:
    def missingSeat(self, seats: List[int]) -> int:
        n = len(seats)
        return n * (n + 1) // 2 - sum(seats)

code.java:
class Solution {
    public int missingSeat(int[] seats) {
        long n = seats.length;
        long left = n * (n + 1) / 2;
        for (int s : seats) left -= s;
        return (int) left;
    }
}

